16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be E.164 form: '+' followed by 8 to 15 digits")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date", columnDefinition = "DATE")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Column(name = "household_size")
67	    private Integer householdSize;
68	
69	    @Column(name = "bulk_signup_warning")
70	    private Boolean bulkSignupWarning;
71	
72	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
73	    private Set<Pet> pets;
74	
75	    public String getAddress() {
76	        return this.address;
77	    }
78	
79	    public void setAddress(String address) {
80	        this.address = address;
81	    }
82	
83	    public String getCity() {
84	        return this.city;
85	    }
86	
87	    public void setCity(String city) {
88	        this.city = city;
89	    }
90	
91	    public String getTelephone() {
92	        return this.telephone;
93	    }
94	
95	    public void setTelephone(String telephone) {
96	        this.telephone = telephone;
97	    }
98	
99	    public String getEmail() {
100	        return this.email;
101	    }
102	
103	    public void setEmail(String email) {
104	        this.email = email;
105	    }
106	
107	    public LocalDate getRegistrationDate() {
108	        return this.registrationDate;
109	    }
110	
111	    public void setRegistrationDate(LocalDate registrationDate) {
112	        this.registrationDate = registrationDate;
113	    }
114	
115	    public String getCustomerCode() {
116	        return this.customerCode;
117	    }
118	
119	    public void setCustomerCode(String customerCode) {
120	        this.customerCode = customerCode;
121	    }
122	
123	    public String getHouseholdId() {
124	        return this.householdId;
125	    }
126	
127	    public void setHouseholdId(String householdId) {
128	        this.householdId = householdId;
129	    }
130	
131	    public Integer getNamesakeCount() {
132	        return this.namesakeCount;
133	    }
134	
135	    public void setNamesakeCount(Integer namesakeCount) {
136	        this.namesakeCount = namesakeCount;
137	    }
138	
139	    public Integer getHouseholdSize() {
140	        return this.householdSize;
141	    }
142	
143	    public void setHouseholdSize(Integer householdSize) {
144	        this.householdSize = householdSize;
145	    }
146	
147	    public Boolean getBulkSignupWarning() {
148	        return this.bulkSignupWarning;
149	    }
150	
151	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
152	        this.bulkSignupWarning = bulkSignupWarning;
153	    }
154	
155	    /**
156	     * The owner's membership level (1 to 3), derived from the creation-time facts it is assigned
157	     * from: start at 1, add 1 when an email is present, add 1 when {@code namesakeCount} is 0, and
158	     * cap at 3. Level 4 is reserved for tenure. Not persisted.
159	     */
160	    @Transient
161	    public Integer getMembershipLevel() {
162	        int level = 1;
163	        if (this.email != null && !this.email.isBlank()) {
164	            level++;
165	        }
166	        if (this.namesakeCount != null && this.namesakeCount == 0) {
167	            level++;
168	        }
169	        return Math.min(level, 3);
170	    }
171	
172	    /**
173	     * The owner's preferred contact channel, derived from whether an email is present:
174	     * {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}. Not persisted.
175	     */
176	    @Transient
177	    public String getContactPreference() {
178	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
179	    }
180	
181	    protected Set<Pet> getPetsInternal() {
182	        if (this.pets == null) {
183	            this.pets = new HashSet<>();
184	        }
185	        return this.pets;
186	    }
187	
188	    protected void setPetsInternal(Set<Pet> pets) {
189	        this.pets = pets;
190	    }
191	
192	    public List<Pet> getPets() {
193	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
194	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
195	        return Collections.unmodifiableList(sortedPets);
196	    }
197	
198	    public void setPets(List<Pet> pets) {
199	        this.pets = new HashSet<>(pets);
200	    }
201	
202	    public void addPet(Pet pet) {
203	        getPetsInternal().add(pet);
204	        pet.setOwner(this);
205	    }
206	
207	    /**
208	     * Return the Pet with the given name, or null if none found for this Owner.
209	     *
210	     * @param name to test
211	     * @return true if pet name is already in use
212	     */
213	    public Pet getPet(String name) {
214	        return getPet(name, false);
215	    }
216	
217	    /**
218	     * Return the Pet with the given name, or null if none found for this Owner.
219	     *
220	     * @param name to test
221	     * @return true if pet name is already in use
222	     */
223	    public Pet getPet(String name, boolean ignoreNew) {
224	        name = name.toLowerCase();
225	        for (Pet pet : getPetsInternal()) {
226	            if (!ignoreNew || !pet.isNew()) {
227	                String compName = pet.getName();
228	                compName = compName.toLowerCase();
229	                if (compName.equals(name)) {
230	                    return pet;
231	                }
232	            }
233	        }
234	        return null;
235	    }
236	
237	    public Pet getPet(Integer petId) {
238	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
239	    }
240	
241	    @Override
242	    public String toString() {
243	        return new ToStringCreator(this)
244	
245	            .append("id", this.getId())
246	            .append("new", this.isNew())
247	            .append("lastName", this.getLastName())
248	            .append("firstName", this.getFirstName())
249	            .append("address", this.address)
250	            .append("city", this.city)
251	            .append("telephone", this.telephone)
252	            .append("email", this.email)
253	            .toString();
254	    }
255	}
