4	
5	/**
6	 * Normalizes telephone numbers to E.164 form.
7	 *
8	 * <p>Rules: strip spaces, dashes and brackets; keep a leading '+' and its country code when
9	 * present; otherwise assume country code '+61' and drop a single leading '0' from the national
10	 * digits. The result is '+' followed by 8 to 15 digits, so '0412 345 678' becomes
11	 * '+61412345678' and '+64 21 123 456' becomes '+6421123456'.
12	 *
13	 * <p>Country-specific national-number length: '+61' requires exactly 9 national digits and '+1'
14	 * requires exactly 10; a number whose national part is the wrong length for its country code is
15	 * rejected. Other country codes are only bound by the general 8-to-15 total-digit rule.
16	 */
17	public final class TelephoneE164 {
18	
19	    private TelephoneE164() {
20	    }
21	
22	    /**
23	     * Converts to E.164, throwing {@link InvalidTelephoneException} when the input cannot form a
24	     * valid E.164 number.
25	     */
26	    public static String normalize(String input) throws InvalidTelephoneException {
27	        String e164 = toE164(input);
28	        if (e164 == null) {
29	            throw new InvalidTelephoneException(input);
30	        }
31	        return e164;
32	    }
33	
34	    /**
35	     * Best-effort conversion to E.164; returns {@code null} when the input cannot form a valid
36	     * E.164 number.
37	     */
38	    public static String toE164(String input) {
39	        if (input == null) {
40	            return null;
41	        }
42	        String cleaned = input.replaceAll("[\\s\\-()]", "");
43	        boolean hasPlus = cleaned.startsWith("+");
44	        String digits = hasPlus ? cleaned.substring(1) : cleaned;
45	        if (digits.isEmpty() || !digits.chars().allMatch(c -> c >= '0' && c <= '9')) {
46	            return null;
47	        }
48	        String e164;
49	        if (hasPlus) {
50	            e164 = digits;
51	        }
52	        else {
53	            if (digits.startsWith("0")) {
54	                digits = digits.substring(1);
55	            }
56	            e164 = "61" + digits;
57	        }
58	        if (e164.length() < 8 || e164.length() > 15) {
59	            return null;
60	        }
61	        if (!hasValidNationalLength(e164)) {
62	            return null;
63	        }
64	        return "+" + e164;
65	    }
66	
67	    /**
68	     * Checks the national-number length for country codes with a fixed requirement: '+61' must
69	     * have 9 national digits and '+1' must have 10. Any other country code passes (its length is
70	     * only bound by the general 8-to-15 total-digit rule).
71	     */
72	    private static boolean hasValidNationalLength(String e164) {
73	        if (e164.startsWith("61")) {
74	            return e164.length() - 2 == 9;
75	        }
76	        if (e164.startsWith("1")) {
77	            return e164.length() - 1 == 10;
78	        }
79	        return true;
80	    }
81	}
